<?php require __DIR__.'/bootstrap.php';messenger_run(function($u){MessengerSecurity::requirePermission('messenger.admin.dashboard');$action=(string)($_GET['action']??'stats');if($action==='audit'){MessengerSecurity::requirePermission('messenger.admin.audit');return Database::fetchAll('SELECT l.*,u.name actor_name,c.title conversation_title FROM chat_audit_logs l LEFT JOIN users u ON u.id=l.actor_id LEFT JOIN chat_conversations c ON c.id=l.conversation_id ORDER BY l.id DESC LIMIT 300');}if($action==='reports'){MessengerSecurity::requirePermission('messenger.admin.reports');return Database::fetchAll('SELECT r.*,u.name reporter_name,m.body message_body,c.title conversation_title FROM chat_reports r JOIN users u ON u.id=r.reported_by JOIN chat_messages m ON m.id=r.message_id JOIN chat_conversations c ON c.id=r.conversation_id ORDER BY r.id DESC LIMIT 300');}return MessengerService::adminStats();});
